# Let me analyze the differences more carefully
inputs = ['dkfbcb', 'khbif', 'xxbux', 'iu', 'yhky']
outputs = ['buckfbcb', 'kagcbif', 'xxbux', 'iu', 'yagcky']

print("Input -> Output differences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")

# Let's look at character positions that differ
print("\nDetailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")
    if inp != out:
        # Find where they differ
        for j, (in_char, out_char) in enumerate(zip(inp, out)):
            if in_char != out_char:
                print(f"  Position {j}: '{in_char}' -> '{out_char}'")
    else:
        print("  No changes")

